"""Compute the result for a game of Hex / Polygon.

The board is a parallelogram of hexagonal fields, represented as text
lines of increasing indentation.  Each cell is a single character:
``X``, ``O`` or ``.`` (empty).

Player ``X`` plays from left to right, player ``O`` plays from top to
bottom.  A player wins when their stones form a connected path between
the two sides they are assigned.
"""


class ConnectGame:
    def __init__(self, board):
        if isinstance(board, str):
            lines = board.splitlines()
        else:
            lines = list(board)
        self.board = [list(line.replace(" ", "")) for line in lines if line.strip()]
        self.height = len(self.board)
        self.width = len(self.board[0]) if self.board else 0

    def get_winner(self):
        if self._connected("X"):
            return "X"
        if self._connected("O"):
            return "O"
        return ""

    def _connected(self, player):
        """Return True if `player` has a connected path across the board."""
        if self.height == 0 or self.width == 0:
            return False

        if player == "X":
            # X plays from left to right.
            start = {(r, 0) for r in range(self.height) if self.board[r][0] == player}
            goal = lambda r, c: c == self.width - 1
        else:
            # O plays from top to bottom.
            start = {(0, c) for c in range(self.width) if self.board[0][c] == player}
            goal = lambda r, c: r == self.height - 1

        if not start:
            return False

        # Neighbours of a cell in the skewed (parallelogram) grid.
        neighbours = ((0, -1), (0, 1), (-1, 0), (-1, 1), (1, -1), (1, 0))

        seen = set(start)
        frontier = list(start)
        while frontier:
            r, c = frontier.pop()
            if goal(r, c):
                return True
            for dr, dc in neighbours:
                nr, nc = r + dr, c + dc
                if 0 <= nr < self.height and 0 <= nc < self.width:
                    if (nr, nc) not in seen and self.board[nr][nc] == player:
                        seen.add((nr, nc))
                        frontier.append((nr, nc))
        return False
